begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.k(n integer) returns uuid language sql immutable as $$select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.k(n),'growth-'||n||'@example.test','{}' from generate_series(1,5)n;
insert into public.organizations(id,name,created_by) values(pg_temp.k(10),'Growth Alpha',pg_temp.k(1)),(pg_temp.k(11),'Growth Beta',pg_temp.k(5));
insert into public.memberships(organization_id,user_id,role) values(pg_temp.k(10),pg_temp.k(1),'OWNER'),(pg_temp.k(10),pg_temp.k(2),'MEMBER'),(pg_temp.k(10),pg_temp.k(3),'ADMIN'),(pg_temp.k(10),pg_temp.k(4),'VIEWER'),(pg_temp.k(11),pg_temp.k(5),'OWNER');
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
select public.set_organization_plugin_enabled(pg_temp.k(10),'marketing',true);
select set_config('request.jwt.claim.sub',pg_temp.k(5)::text,true);
select public.set_organization_plugin_enabled(pg_temp.k(11),'marketing',true);
do $$declare n integer;org uuid;actor uuid;begin for n in 0..1 loop
  org:=pg_temp.k(10+n);actor:=pg_temp.k(case when n=0 then 1 else 5 end);
  perform set_config('request.jwt.claim.sub',actor::text,true);
  insert into public.marketing_research(id,organization_id,title,content,category,created_by,updated_by) values(pg_temp.k(50+n),org,'Interview notes','Synthetic interview observation','CUSTOMER',actor,actor);
  insert into public.tasks(id,organization_id,title,created_by,updated_by) values(pg_temp.k(60+n),org,'Interview users',actor,actor);
  insert into public.marketing_campaigns(id,organization_id,name,objective,created_by,updated_by) values(pg_temp.k(70+n),org,'Message test','Compare clear onboarding messages',actor,actor);
  insert into public.jobs(id,organization_id,created_by,plugin_id,job_type,capability,execution_class,status,timeout_seconds,error_category,completed_at,cancellation_requested_at,cancelled_at) values(pg_temp.k(100+n),org,actor,'marketing','marketing.external-research','marketing.research.read','SERVERLESS','CANCELLED',55,'cancelled',now(),now(),now());
  insert into public.marketing_external_research_runs(id,organization_id,job_id,created_by,invocation_key,request_snapshot,status,requested_source_count,completed_at,failure_category,evidence_count) values(pg_temp.k(110+n),org,pg_temp.k(100+n),actor,pg_temp.k(150+n),'{}','CANCELLED',1,now(),'cancelled',1);
  insert into public.marketing_external_research_sources(id,organization_id,run_id,source_key,adapter,status,canonical_url,title,fetched_at,content_hash) values(pg_temp.k(120+n),org,pg_temp.k(110+n),'SRC-1','rss-atom','SUCCEEDED','https://example.test/research','Synthetic source',now(),repeat('a',64));
  insert into public.marketing_external_research_evidence(id,organization_id,run_id,source_id,evidence_id,evidence_type,excerpt,title) values(pg_temp.k(130+n),org,pg_temp.k(110+n),pg_temp.k(120+n),'EVID-1','FEED_ITEM','Synthetic source excerpt','Observed setup confusion');
  insert into public.marketing_external_research_reports(id,organization_id,run_id,structured_report,created_by) values(pg_temp.k(140+n),org,pg_temp.k(110+n),'{"contentOpportunities":[{"title":"Explain the first useful action"}]}',actor);
end loop;end$$;
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
insert into public.boards(id,organization_id,title,created_by,updated_by) values(pg_temp.k(80),pg_temp.k(10),'Growth thinking',pg_temp.k(1),pg_temp.k(1));
insert into public.board_elements(id,organization_id,board_id,element_type,x,y,width,height,content,created_by,updated_by) values(pg_temp.k(90),pg_temp.k(10),pg_temp.k(80),'STICKY',0,0,200,160,'{"text":"We believe a clear first step reduces setup abandonment"}',pg_temp.k(1),pg_temp.k(1));
create function pg_temp.hfields(p_id uuid,p_status text) returns jsonb language sql as $$select jsonb_build_object('title',title,'statement',statement,'status',p_status,'confidence',confidence,'ownerId',owner_id,'archived',archived_at is not null) from public.marketing_hypotheses where id=p_id$$;
create function pg_temp.efields(p_id uuid,p_status text,p_criteria text default null) returns jsonb language sql as $$select jsonb_build_object('title',title,'hypothesisId',hypothesis_id,'testPlan',test_plan,'successCriteria',coalesce(p_criteria,success_criteria),'status',p_status,'ownerId',owner_id,'startsOn',starts_on,'endsOn',ends_on,'archived',archived_at is not null) from public.marketing_experiments where id=p_id$$;
create function pg_temp.native_card(p_id uuid,p_reference jsonb,p_metadata jsonb default '{}') returns void language plpgsql as $$begin
  perform public.apply_board_operation(pg_temp.k(80),jsonb_build_array(jsonb_build_object('id',p_id,'element_type','ENTITY_CARD','x',240,'y',0,'width',280,'height',160,'rotation',0,'z_index',10,'parent_id',null,'locked',false,'content',jsonb_build_object('reference',p_reference),'style','{}'::jsonb,'metadata',p_metadata)),array[]::uuid[]);
end$$;
set local role authenticated;
select lives_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(20),'{"title":"Setup confidence","statement":"We believe a clear first step reduces abandonment","ownerId":"00000000-0000-4000-8000-000000000002"}',null)$$,'owner creates a focused belief');
select is((select status from public.marketing_hypotheses where id=pg_temp.k(20)),'DRAFT','initial belief is draft');
select throws_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(22),'{"title":"Bad owner","statement":"A testable belief","ownerId":"00000000-0000-4000-8000-000000000005"}',null)$$,'22023',null,'foreign owner is rejected');
select throws_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(22),'{"title":"Too certain","statement":"A testable belief","status":"PROVEN"}',null)$$,'23514',null,'proven is not a hypothesis state');
select lives_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(20),pg_temp.hfields(pg_temp.k(20),'READY_TO_TEST'),(select updated_at from public.marketing_hypotheses where id=pg_temp.k(20)))$$,'hypothesis update is version checked');
select throws_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(20),pg_temp.hfields(pg_temp.k(20),'DRAFT'),'2000-01-01')$$,'PT409',null,'stale update cannot overwrite newer work');
select lives_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(20),jsonb_build_object('kind','evidence','id',pg_temp.k(130),'runId',pg_temp.k(110),'evidenceKey','EVID-1'))$$,'exact evidence citation');
select lives_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(20),jsonb_build_object('kind','note','id',pg_temp.k(50)))$$,'manual note remains separate');
select lives_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(20),jsonb_build_object('kind','opportunity','id',pg_temp.k(140),'index',0))$$,'candidate binds exact immutable report/index');
select throws_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(20),jsonb_build_object('kind','evidence','id',pg_temp.k(130),'runId',pg_temp.k(111),'evidenceKey','EVID-1'))$$,'42501',null,'an evidence UUID cannot silently change run');
select throws_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(20),jsonb_build_object('kind','evidence','id',pg_temp.k(131),'runId',pg_temp.k(111),'evidenceKey','EVID-1'))$$,'42501',null,'foreign evidence is denied');
select throws_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(20),jsonb_build_object('kind','note','id',pg_temp.k(51)))$$,'42501',null,'foreign manual note is denied');
select throws_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(20),jsonb_build_object('kind','opportunity','id',pg_temp.k(141),'index',0))$$,'42501',null,'foreign opportunity is denied');
select throws_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(20),jsonb_build_object('kind','opportunity','id',pg_temp.k(140),'index',3))$$,'42501',null,'missing candidate is not invented');
select lives_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(20),jsonb_build_object('kind','note','id',pg_temp.k(50)))$$,'repeated citation is idempotent');
select is((select count(*) from public.marketing_hypothesis_sources where hypothesis_id=pg_temp.k(20)),3::bigint,'no duplicate citation');
select throws_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(23),'{"title":"Atomic source","statement":"A new belief"}',null,jsonb_build_object('kind','note','id',pg_temp.k(51)))$$,'42501',null,'invalid creation source rolls back belief');
select is((select count(*) from public.marketing_hypotheses where id=pg_temp.k(23)),0::bigint,'failed source leaves no orphan belief');
select lives_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(30),jsonb_build_object('title','Test clear first step','hypothesisId',pg_temp.k(20),'status','PLANNED'),null)$$,'create planned qualitative experiment');
select is((select source_count from public.marketing_growth_counts(pg_temp.k(10),array[pg_temp.k(20)])),3::bigint,'batched source counts honor RLS and canonical links');
select is((select experiment_count from public.marketing_growth_counts(pg_temp.k(10),array[pg_temp.k(20)])),1::bigint,'batched experiment counts use actual relationships');
select throws_ok($$select * from public.marketing_growth_counts(pg_temp.k(10),array_fill(pg_temp.k(20),array[26]))$$,'22023',null,'count aggregation is bounded to a list page');
select throws_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(31),jsonb_build_object('title','Wrong belief','hypothesisId',pg_temp.k(999)),null)$$,'42501',null,'unavailable hypothesis is denied');
select throws_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(30),pg_temp.efields(pg_temp.k(30),'RUNNING'),(select updated_at from public.marketing_experiments where id=pg_temp.k(30)))$$,'23514',null,'running needs nonempty criteria');
select throws_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(30),pg_temp.efields(pg_temp.k(30),'COMPLETE'),(select updated_at from public.marketing_experiments where id=pg_temp.k(30)))$$,'22023',null,'completion cannot bypass evaluation');
select lives_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(30),pg_temp.efields(pg_temp.k(30),'RUNNING','At least 7 of 10 participants complete setup without assistance'),(select updated_at from public.marketing_experiments where id=pg_temp.k(30)))$$,'qualitative success criteria allow running');
select throws_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(30),pg_temp.efields(pg_temp.k(30),'DRAFT'),(select updated_at from public.marketing_experiments where id=pg_temp.k(30)))$$,'22023',null,'running cannot silently return to draft');
select lives_ok($$select public.link_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'task',pg_temp.k(60))$$,'link canonical Core Task');
select lives_ok($$select public.link_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'campaign',pg_temp.k(70))$$,'link canonical Campaign');
select lives_ok($$select public.link_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'task',pg_temp.k(60))$$,'execution link repeat is idempotent');
select is((select count(*) from public.marketing_experiment_links where experiment_id=pg_temp.k(30)),2::bigint,'links do not duplicate execution');
select throws_ok($$select public.link_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'task',pg_temp.k(61))$$,'42501',null,'foreign Task denied');
select throws_ok($$select public.link_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'campaign',pg_temp.k(71))$$,'42501',null,'foreign Campaign denied');
select throws_ok($$select public.evaluate_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'SUPPORTED','Eight of ten completed',(select updated_at from public.marketing_experiments where id=pg_temp.k(30)))$$,'22023',null,'evaluate is a deliberate stage');
select lives_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(30),pg_temp.efields(pg_temp.k(30),'EVALUATING'),(select updated_at from public.marketing_experiments where id=pg_temp.k(30)))$$,'move to evaluating');
select throws_ok($$select public.evaluate_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'PROVEN','Eight of ten completed',(select updated_at from public.marketing_experiments where id=pg_temp.k(30)))$$,'23514',null,'absolute-truth outcome rejected');
select throws_ok($$select public.evaluate_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'SUPPORTED',null,(select updated_at from public.marketing_experiments where id=pg_temp.k(30)))$$,'23514',null,'SQL NULL cannot bypass required result summary');
select lives_ok($$select public.evaluate_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'SUPPORTED','Eight of ten participants completed without help',(select updated_at from public.marketing_experiments where id=pg_temp.k(30)),null,false)$$,'complete without forcing a Learning or hypothesis change');
select is((select status from public.marketing_hypotheses where id=pg_temp.k(20)),'READY_TO_TEST','hypothesis state did not silently change');
select is((select count(*) from public.marketing_learnings),0::bigint,'Learning is optional');
select is((select cardinality(evaluated_source_ids) from public.marketing_experiments where id=pg_temp.k(30)),3,'evaluation freezes exact source identities');
select throws_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(30),pg_temp.efields(pg_temp.k(30),'COMPLETE','Changed criteria'),(select updated_at from public.marketing_experiments where id=pg_temp.k(30)))$$,'22023',null,'completed criteria cannot be rewritten');
select throws_ok($$select public.link_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'task',pg_temp.k(60),true)$$,'22023',null,'completed execution provenance is retained');
select lives_ok($$select public.save_marketing_learning(pg_temp.k(10),pg_temp.k(40),pg_temp.k(30),'First step clarity','Clear first steps helped this sample complete setup','MEDIUM')$$,'record a reviewed Learning from the completed experiment');
select throws_ok($$select public.save_marketing_learning(pg_temp.k(10),pg_temp.k(41),pg_temp.k(30),'Duplicate conclusion','A second canonical Learning','HIGH')$$,'23505',null,'one reviewed Learning per experiment');
select is((select count(*) from public.knowledge_memories),0::bigint,'completion and Learning create zero memory');
select lives_ok($$select public.promote_marketing_learning(pg_temp.k(10),pg_temp.k(40),'INSIGHT','Reviewed setup insight','Clear first steps helped this sample')$$,'explicit reviewed promotion uses Core mutation');
select is((select count(*) from public.knowledge_memories),1::bigint,'explicit promotion creates one memory');
select lives_ok($$select public.promote_marketing_learning(pg_temp.k(10),pg_temp.k(40),'FACT','Changed retry title','Changed retry content')$$,'retry recovers existing memory without replacing it');
select is((select title from public.knowledge_memories limit 1),'Reviewed setup insight','retry cannot silently overwrite memory');
select is((select domain::text||':'||provenance::text from public.knowledge_memories limit 1),'company:HUMAN','human company scope only');
select is((select source_reference from public.knowledge_memories limit 1),'Learning '||pg_temp.k(40)::text||'; Experiment '||pg_temp.k(30)::text,'memory retains internal source identities');
select lives_ok($$select public.prepare_board_entity_conversion(pg_temp.k(160),pg_temp.k(80),'marketing.hypothesis','{"title":"Board belief","statement":"We believe clear setup helps","status":"DRAFT","confidence":"LOW","ownerId":""}',array[pg_temp.k(90)])$$,'prepare Sticky to Hypothesis in existing receipt domain');
select lives_ok($$select public.create_marketing_growth_from_board(pg_temp.k(160))$$,'create Hypothesis before Board linking');
select lives_ok($$select public.create_marketing_growth_from_board(pg_temp.k(160))$$,'retry after omitted Board link reuses Hypothesis');
select is((select count(*) from public.marketing_hypotheses where board_conversion_id=pg_temp.k(160)),1::bigint,'partial Board failure creates one Hypothesis');
select is((select count(*) from public.board_elements where metadata->>'conversionId'=pg_temp.k(160)::text),0::bigint,'creation did not claim a successful Board link');
select throws_ok($$update public.marketing_hypotheses set title='Direct overwrite' where id=pg_temp.k(20)$$,'42501',null,'browser cannot bypass actor-deriving mutation domain');
select set_config('request.jwt.claim.sub',pg_temp.k(4)::text,true);
select is((select count(*) from public.marketing_hypotheses),2::bigint,'VIEWER reads authorized beliefs');
select throws_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(24),'{"title":"Viewer write","statement":"A belief"}',null)$$,'42501',null,'VIEWER create denied');
select throws_ok($$select public.link_marketing_experiment(pg_temp.k(10),pg_temp.k(30),'task',pg_temp.k(60))$$,'42501',null,'VIEWER link denied');
select throws_ok($$select public.promote_marketing_learning(pg_temp.k(10),pg_temp.k(40),'INSIGHT','Viewer promotion','Not allowed')$$,'42501',null,'VIEWER promotion denied');
select set_config('request.jwt.claim.sub',pg_temp.k(5)::text,true);
select is((select count(*) from public.marketing_hypotheses where organization_id=pg_temp.k(10)),0::bigint,'foreign organization reads no beliefs');
select is((select count(*) from public.marketing_experiment_links where organization_id=pg_temp.k(10)),0::bigint,'foreign organization reads no links');
select throws_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(20),'{"title":"Foreign update","statement":"Not allowed"}',null)$$,'42501',null,'foreign mutation denied');
select set_config('request.jwt.claim.sub',pg_temp.k(2)::text,true);
select lives_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(24),'{"title":"Member belief","statement":"A member testable belief"}',null)$$,'MEMBER can collaborate');
select set_config('request.jwt.claim.sub',pg_temp.k(3)::text,true);
select lives_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(25),'{"title":"Admin belief","statement":"An admin testable belief"}',null)$$,'ADMIN can collaborate');
reset role;
update public.memberships set removed_at=now() where organization_id=pg_temp.k(10) and user_id=pg_temp.k(2);
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.k(2)::text,true);
select is((select count(*) from public.marketing_hypotheses),0::bigint,'revoked member loses all growth reads');
select throws_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(26),'{"title":"Revoked write","statement":"Not allowed"}',null)$$,'42501',null,'revoked member mutation denied');
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
select public.set_organization_plugin_enabled(pg_temp.k(10),'marketing',false);
select is((select count(*) from public.marketing_hypotheses),0::bigint,'disabled Marketing hides growth records');
select throws_ok($$select public.create_marketing_growth_from_board(pg_temp.k(160))$$,'42501',null,'disabled plugin blocks conversion recovery');
select throws_ok($$select public.promote_marketing_learning(pg_temp.k(10),pg_temp.k(40),'INSIGHT','Disabled promotion','Not allowed')$$,'42501',null,'disabled plugin blocks promotion');
select public.set_organization_plugin_enabled(pg_temp.k(10),'marketing',true);
select is((select count(*) from public.marketing_hypotheses),4::bigint,'reenable preserves original records');
select lives_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(31),jsonb_build_object('title','A second qualitative test','hypothesisId',pg_temp.k(20),'successCriteria','Compare interview responses','status','PLANNED'),null)$$,'another experiment can test the same belief');
select lives_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(31),pg_temp.efields(pg_temp.k(31),'RUNNING'),(select updated_at from public.marketing_experiments where id=pg_temp.k(31)))$$,'second test running');
select lives_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(31),pg_temp.efields(pg_temp.k(31),'EVALUATING'),(select updated_at from public.marketing_experiments where id=pg_temp.k(31)))$$,'second test evaluating');
select lives_ok($$select public.evaluate_marketing_experiment(pg_temp.k(10),pg_temp.k(31),'INCONCLUSIVE','Responses were mixed',(select updated_at from public.marketing_experiments where id=pg_temp.k(31)),jsonb_build_object('id',pg_temp.k(41),'title','Need a larger sample','conclusion','The available sample does not distinguish the alternatives','confidence','LOW'),true)$$,'explicit optional Learning and Hypothesis update commit atomically');
select is((select status from public.marketing_hypotheses where id=pg_temp.k(20)),'INCONCLUSIVE','Hypothesis changes only after explicit choice');
select is((select count(*) from public.knowledge_memories),1::bigint,'optional Learning did not promote another memory');
select lives_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(32),jsonb_build_object('title','Cancelled test','hypothesisId',pg_temp.k(20)),null)$$,'draft cancellation fixture');
select lives_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(32),pg_temp.efields(pg_temp.k(32),'CANCELLED'),(select updated_at from public.marketing_experiments where id=pg_temp.k(32)))$$,'cancel without fabricated result');
select throws_ok($$select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(32),pg_temp.efields(pg_temp.k(32),'RUNNING','Restart'),(select updated_at from public.marketing_experiments where id=pg_temp.k(32)))$$,'22023',null,'cancelled test cannot silently restart');
select throws_ok($$select public.save_marketing_learning(pg_temp.k(10),pg_temp.k(42),pg_temp.k(32),'Invented conclusion','No completed evaluation','HIGH')$$,'42501',null,'Learning requires a completed result');
select lives_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(20),jsonb_build_object('kind','note','id',pg_temp.k(50)),true)$$,'current belief sources may evolve');
select is((select cardinality(evaluated_source_ids) from public.marketing_experiments where id=pg_temp.k(30)),3,'earlier completed evaluation retains removed source identity');
select lives_ok($$select pg_temp.native_card(pg_temp.k(91),jsonb_build_object('entityType','marketing.research-evidence','entityId',pg_temp.k(130),'organizationId',pg_temp.k(10),'sourcePlugin','marketing','immutable',jsonb_build_object('runId',pg_temp.k(110),'evidenceId','EVID-1')))$$,'native exact Evidence source card');
select lives_ok($$select public.prepare_board_entity_conversion(pg_temp.k(161),pg_temp.k(80),'marketing.hypothesis','{"title":"Evidence-led belief","statement":"We believe the first step is unclear","status":"DRAFT","confidence":"LOW","ownerId":""}',array[pg_temp.k(91)])$$,'prepare explicit Evidence to Hypothesis');
select lives_ok($$select public.create_marketing_growth_from_board(pg_temp.k(161))$$,'domain creates belief and exact citation atomically');
select is((select count(*) from public.marketing_hypothesis_sources where hypothesis_id=(select entity_id from public.board_entity_conversions where id=pg_temp.k(161)) and evidence_id=pg_temp.k(130) and evidence_run_id=pg_temp.k(110) and evidence_key='EVID-1'),1::bigint,'Board conversion preserves exact immutable provenance');
select lives_ok($$select pg_temp.native_card(card_id,jsonb_build_object('entityType',entity_type,'entityId',entity_id,'organizationId',organization_id,'sourcePlugin','marketing'),jsonb_build_object('conversionId',id)) from public.board_entity_conversions where id=pg_temp.k(161)$$,'link the canonical new Hypothesis using its reserved card identity');
select lives_ok($$select public.prepare_board_entity_conversion(pg_temp.k(162),pg_temp.k(80),'marketing.experiment',jsonb_build_object('title','Test the observed barrier','hypothesisId',(select entity_id::text from public.board_entity_conversions where id=pg_temp.k(161)),'status','DRAFT','testPlan','','successCriteria','','ownerId','','startsOn','','endsOn',''),array[(select card_id from public.board_entity_conversions where id=pg_temp.k(161))])$$,'prepare Hypothesis to Experiment in the existing receipt domain');
select lives_ok($$select public.create_marketing_growth_from_board(pg_temp.k(162))$$,'create canonical Experiment before Board linking');
select lives_ok($$select public.create_marketing_growth_from_board(pg_temp.k(162))$$,'failed/missing Board link retry reuses Experiment');
select is((select count(*) from public.marketing_experiments where board_conversion_id=pg_temp.k(162)),1::bigint,'one Experiment after repeated recovery');
select is((select hypothesis_id from public.marketing_experiments where board_conversion_id=pg_temp.k(162)),(select entity_id from public.board_entity_conversions where id=pg_temp.k(161)),'Experiment binds the selected canonical Hypothesis');
select lives_ok($$select public.prepare_board_entity_conversion(pg_temp.k(164),pg_temp.k(80),'core.task','{"title":"Existing Task contract","priority":"MEDIUM","description":"No new native conversion"}',array[pg_temp.k(91)])$$,'generic preparation allocates no canonical work');
select throws_ok($$select public.create_task_from_board(pg_temp.k(164))$$,'42501',null,'existing Task creation remains restricted to its plaintext source contract');
select lives_ok($$select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(26),'{"title":"Bounded evidence","statement":"A testable belief with bounded citations"}',null)$$,'bounded source fixture');
insert into public.marketing_research(id,organization_id,title,content,category,created_by,updated_by) select pg_temp.k(200+n),pg_temp.k(10),'Source '||n,'Synthetic source','OTHER',pg_temp.k(1),pg_temp.k(1) from generate_series(1,31)n;
do $$begin for n in 1..30 loop perform public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(26),jsonb_build_object('kind','note','id',pg_temp.k(200+n)));end loop;end$$;
select throws_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(26),jsonb_build_object('kind','note','id',pg_temp.k(231)))$$,'22023',null,'new citations respect the 30-source bound');
select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(26),jsonb_build_object('kind','note','id',pg_temp.k(201)),true);
select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(26),jsonb_build_object('kind','note','id',pg_temp.k(231)),false);
select throws_ok($$select public.link_marketing_hypothesis_source(pg_temp.k(10),pg_temp.k(26),jsonb_build_object('kind','note','id',pg_temp.k(201)),false)$$,'22023',null,'restoring citations cannot bypass the bound');
select is((select count(*) from public.ai_runs),0::bigint,'all growth actions made zero model executions');
select is((select count(*) from public.jobs where organization_id=pg_temp.k(10)),1::bigint,'no growth action enqueued work');
select * from finish();
rollback;
